-- SECTION R3: ROLLBACK COMPONENT STAGES
DROP FUNCTION IF EXISTS app_private.read_platform_configuration();
REVOKE SELECT (key, value) ON public.system_config FROM sympowork_context_owner;

DROP FUNCTION IF EXISTS app_private.revoke_presented_session(text);
REVOKE DELETE ON public.sessions FROM sympowork_context_owner;

DROP FUNCTION IF EXISTS app_private.append_failed_login();
DROP POLICY IF EXISTS failed_login_append ON public.audit_logs;
REVOKE INSERT (action, resource) ON public.audit_logs FROM sympowork_context_owner;

DROP FUNCTION IF EXISTS app_private.begin_request_context(text);
DROP FUNCTION IF EXISTS app_private.valid_request_context();
DROP FUNCTION IF EXISTS app_private.current_user_id();
DROP FUNCTION IF EXISTS app_private.current_organization_id();
DROP FUNCTION IF EXISTS app_private.is_platform_owner();
DROP FUNCTION IF EXISTS app_private.current_request_user();
DROP FUNCTION IF EXISTS app_private.end_request_context();

DROP POLICY IF EXISTS membership_context_bootstrap ON public.memberships;
REVOKE USAGE ON SCHEMA public FROM sympowork_context_owner;
REVOKE SELECT ON public.sessions, public.users, public.memberships, public.organizations FROM sympowork_context_owner;

DROP TABLE IF EXISTS app_private.request_context_key;
DROP SCHEMA IF EXISTS app_private CASCADE;
DROP ROLE IF EXISTS sympowork_context_owner;

COMMIT;
